public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int amount = sc.nextInt();
        so.println(minCoinCount(amount));
    }

    static int minCoinCount(int amount) {
        int[] coins = {1000, 500, 100, 50, 20, 10, 5, 2, 1};
        int count = 0;
        for (int coin : coins) {
            if (amount == 0) break;
            count += amount / coin;
            amount %= coin;
        }
        return count;
    }
}

