        int[] start = new int[n];
        for (int i = 0; i < n; i++) start[i] = sc.nextInt();
        int[] end = new int[n];
        for (int i = 0; i < n; i++) end[i] = sc.nextInt();
        System.out.println(clashCount(start, end));
    }

    static int clashCount(int[] start, int[] end) {
        int count = 0;
        for (int i = 0; i < start.length; i++) {
            for (int j = i + 1; j < start.length; j++) {
                if (start[i] < end[j] && start[j] < end[i]) count++;
            }
        }
        return count;
    }
}

