        int[] discounts = new int[n];
        for (int i = 0; i < n; i++) discounts[i] = sc.nextInt();
        int k = sc.nextInt();
        System.out.println(topDiscountSum(discounts, k));
    }

    static int topDiscountSum(int[] discounts, int k) {
        int[] sorted = discounts.clone();
        Arrays.sort(sorted);
        int sum = 0;
        for (int i = sorted.length - k; i < sorted.length; i++) sum += sorted[i];
        return sum;
    }
}

