public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] weights = new int[n];
        for (int i = 0; i < n; i++) weights[i] = sc.nextInt();
        int cap = sc.nextInt();
        System.out.println(maxOrders(weights, cap));
    }

    static int maxOrders(int[] weights, int cap) {
        int[] sorted = weights.clone();
        Arrays.sort(sorted);
        int count = 0;
        for (int w : sorted) {
            if (w > cap) break;
            cap -= w;
            count++;
        }
        return count;
    }
}

