public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int amount = sc.nextInt();
        System.out.println(registerCoins(amount));
    }

    static int registerCoins(int amount) {
        int[] coins = {1000, 500, 100, 50, 20, 10, 5, 2, 1};
        int used = 0;
        for (int coin : coins) {
            if (amount <= 0) break;
            if (coin <= amount) {
                amount -= coin;
                used++;
            }
        }
        return used;
    }
}

