public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] people = new int[n];
        for (int i = 0; i < n; i++) people[i] = sc.nextInt();
        int limit = sc.nextInt();
        so.println(minBoats(people, limit));
    }

    static int minBoats(int[] people, int limit) {
        int[] sorted = people.clone();
        Arrays.sort(sorted);
        int i = 0, j = sorted.length - 1, boats = 0;
        while (i <= j) {
            if (sorted[i] + sorted[j] <= limit) i++;
            j--;
            boats++;
        }
        return boats;
    }
}

