        int[] deadlines = new int[n];
        for (int i = 0; i < n; i++) deadlines[i] = sc.nextInt();
        so.println(maxJobs(deadlines));
    }

    static int maxJobs(int[] deadlines) {
        int[] sorted = deadlines.clone();
        Arrays.sort(sorted);
        int time = 0, done = 0;
        for (int d : sorted) {
            if (time < d) {
                time++;
                done++;
            }
        }
        return done;
    }
}

