public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] start = new int[n];
        for (int i = 0; i < n; i++) start[i] = sc.nextInt();
        int[] end = new int[n];
        for (int i = 0; i < n; i++) end[i] = sc.nextInt();
        so.println(minRemovals(start, end));
    }

    static int minRemovals(int[] start, int[] end) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> end[a] - end[b]);
        int kept = 0;
        long lastEnd = Long.MIN_VALUE;
        for (int i : idx) {
            if (start[i] >= lastEnd) {
                kept++;
                lastEnd = end[i];
            }
        }
        return n - kept;
    }
}

