public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] wt = new int[n];
        for (int i = 0; i < n; i++) wt[i] = sc.nextInt();
        int[] val = new int[n];
        for (int i = 0; i < n; i++) val[i] = sc.nextInt();
        int cap = sc.nextInt();
        so.printf(Locale.ROOT, "%.2f%n", fractionalKnapsack(wt, val, cap));
    }

    static double fractionalKnapsack(int[] wt, int[] val, int cap) {
        int n = wt.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> val[b] * wt[a] - val[a] * wt[b]);
        double total = 0.0;
        int room = cap;
        for (int i : idx) {
            if (room <= 0) break;
            if (wt[i] <= room) {
                total += val[i];
                room -= wt[i];
            } else {
                total += (double) val[i] * room / wt[i];
                room = 0;
            }
        }
        return total;
    }
}

