public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arrival = new int[n];
        for (int i = 0; i < n; i++) arrival[i] = sc.nextInt();
        int[] departure = new int[n];
        for (int i = 0; i < n; i++) departure[i] = sc.nextInt();
        so.println(minPlatforms(arrival, departure));
    }

    static int minPlatforms(int[] arrival, int[] departure) {
        int[] arr = arrival.clone();
        int[] dep = departure.clone();
        Arrays.sort(arr);
        Arrays.sort(dep);
        int platforms = 0, best = 0;
        int i = 0, j = 0;
        while (i < arr.length) {
            if (arr[i] < dep[j]) {
                platforms++;
                if (platforms > best) best = platforms;
                i++;
            } else {
                platforms--;
                j++;
            }
        }
        return best;
    }
}

