    }

    static int minArrows(int[] start, int[] end) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> end[a] - end[b]);
        int arrows = 0;
        long shot = Long.MIN_VALUE;
        for (int i : idx) {
            if (start[i] > shot) {
                arrows++;
                shot = end[i];
            }
        }
        return arrows;
    }
}
